arguments.command:
cd /d/tmp2b/fm24-db && py -V:3.12 -I - <<'EOF'
import json
d=json.load(open('scratch/t07/out/naming_result.json',encoding='utf-8'))
for r in d['results']:
    if r['type_id'] in (2,6,21,47):
        print('=== type',r['type_id'],r['entity'],r.get('reader_body'))
        for arch,v in r['archives'].items():
            print('  [',arch,'] bw=',v['business_width'],'window',v['window'])
            for f in v['fields']:
                print(f"    idx={f['idx']} off={f['row_off']:>3} w={f['width']} obj={f['object_off']} field={f['field']!r} conf={f['confidence']} codes={f['codes']}")
EOF

